// Compares incoming and output state and decides pass/fail.
function toBytes(sizeText) {
  if (typeof sizeText === 'number') return sizeText;
  const m = String(sizeText ?? '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)/i);
  if (!m) return 0;
  const n = parseFloat(m[1]); const u = m[2].toLowerCase();
  return u === 'gb' ? n * 1e9 : u === 'mb' ? n * 1e6 : u === 'kb' ? n * 1e3 : n;
}
const cfg = $('Configuration').first().json;
const before = $('Record Incoming State').first().json;
const truthy = v => v === true || String(v) === 'true';
const out = [];
for (const item of $input.all()) {
  const after = item.json;
  const reasons = [];
  const claim = String(after.pdfa ?? '');
  if (!claim || /none|false/i.test(claim)) reasons.push('Output does not carry a PDF/A claim');
  if (truthy(after.contains_javascript)) reasons.push('Output still contains JavaScript');
  if (truthy(after.contains_embedded_file)) reasons.push('Output still contains embedded files');
  if (truthy(after.contains_xfa)) reasons.push('Output still contains XFA');
  if (truthy(after.image_only)) reasons.push('Output has no text layer (OCR did not apply)');
  if (Number(after.page_count) !== Number(before.incoming.page_count)) reasons.push(`Page count changed: ${before.incoming.page_count} -> ${after.page_count}`);
  const outBytes = toBytes(item.binary?.data?.fileSize);
  const inBytes = toBytes(before.originalSize);
  const report = {
    file: before.fileName,
    processedAt: new Date().toISOString(),
    pass: reasons.length === 0,
    reasons,
    target: { pdfAVersion: cfg.pdfAVersion, ocrLanguages: cfg.ocrLanguages },
    sizeBefore: before.originalSize, sizeAfter: item.binary?.data?.fileSize ?? '',
    sizeChangePct: inBytes ? Math.round((outBytes / inBytes - 1) * 1000) / 10 : null,
    incoming: before.incoming,
    output: { pdfa: after.pdfa, contains_javascript: after.contains_javascript, contains_embedded_file: after.contains_embedded_file, contains_xfa: after.contains_xfa, image_only: after.image_only, page_count: after.page_count, pdf_version: after.pdf_version },
  };
  const base = String(before.fileName ?? 'file.pdf').replace(/\.pdf$/i, '');
  out.push({ json: { report, outputFileName: `${base}_${String(cfg.pdfAVersion).replace('/', '')}.pdf`, reportFileName: `${base}_sanitize.json`, reportText: JSON.stringify(report, null, 2) }, binary: item.binary });
}
return out;

